const canvas = document.querySelector("#c");
const ctx = canvas.getContext("2d");
const game = {
  stars: [
    { x: 30, y: 0, vy: 1 },
    { x: 100, y: -40, vy: 1.5 },
    { x: 160, y: -10, vy: 0.8 },
  ],
  missed: 0,
  over: false,
};

function update() {
  // drop them, count the missed ones, end the game if needed
  if (game.over) return;
  for (const s of game.stars) {
    s.y += s.vy;
  }
  const before = game.stars.length;
  game.stars = game.stars.filter((s) => s.y <= canvas.height);
  game.missed += before - game.stars.length;
  if (game.missed >= 3) {
    game.over = true;
    document.querySelector("#info").textContent = `Game over! Missed: ${game.missed}`;
  }
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = "#f7df1e";
  for (const s of game.stars) ctx.fillRect(s.x, s.y, 8, 8);
}

function loop() {
  update();
  draw();
  requestAnimationFrame(loop);
}
requestAnimationFrame(loop);

