const canvas = document.querySelector("#game");
const ctx = canvas.getContext("2d");
const info = document.querySelector("#info");

const ship = { x: 20, y: 150, w: 30, h: 20, vx: 3 };
let stars = [
  { x: 120, y: 155, w: 12, h: 12 },
  { x: 200, y: 150, w: 12, h: 12 },
  { x: 260, y: 160, w: 12, h: 12 },
];
let score = 0;

function update() {
  ship.x += ship.vx;
  if (ship.x < 0 || ship.x + ship.w > canvas.width) {
    ship.x = Math.max(0, Math.min(ship.x, canvas.width - ship.w));
    ship.vx = -ship.vx;
  }
}

function draw() {
  ctx.fillStyle = "#0b1026";
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = "#f7df1e";
  for (const s of stars) ctx.fillRect(s.x, s.y, s.w, s.h);
  ctx.fillStyle = "#4fc3f7";
  ctx.fillRect(ship.x, ship.y, ship.w, ship.h);
}

function hits(a, b) {
  // AABB: four conditions
  return a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;
}

function collect() {
  // remove the stars that touch, add to the score, update #info
  const before = stars.length;
  stars = stars.filter((s) => !hits(ship, s));
  score += before - stars.length;
  if (stars.length === 0) {
    info.textContent = "Well done! All the stars are collected.";
  } else {
    info.textContent = `Score: ${score}`;
  }
}

function step() {
  // update → collect → draw
  update();
  collect();
  draw();
}

function loop() {
  step();
  requestAnimationFrame(loop);
}
requestAnimationFrame(loop);
draw();
